class Temperaturen  
{  
    static void Main(string[] args)  
    {        while (true)  
        {            Console.Write(&quot;Enter a number (or type &#039;exit&#039; to quit): &quot;);  
            var input = Console.ReadLine();  

            if (input == null || input.Equals(&quot;exit&quot;, StringComparison.OrdinalIgnoreCase))  
            {                break;  
            }  
            double temperature;  
            while (!double.TryParse(input, out temperature))  
            {                Console.ForegroundColor = ConsoleColor.Red;  
                Console.WriteLine(&quot;Invalid input. Please enter a valid number.&quot;);  
                Console.ResetColor();  
                Console.Write(&quot;Try again (or type &#039;exit&#039;): &quot;);  
        input = Console.ReadLine();  
        if (input == null || input.Equals(&quot;exit&quot;, StringComparison.OrdinalIgnoreCase))  
                {                    return;  
                }            }  
            Console.Write(&quot;Convert to (Fahrenheit/Kelvin): &quot;);  
            var choice = Console.ReadLine();  

            if (choice == null || choice.Equals(&quot;exit&quot;, StringComparison.OrdinalIgnoreCase))  
            {                break;  
            }  
            switch (choice)  
            {                case &quot;Fahrenheit&quot;:  
                    CelsiusToFahrenheit(temperature);  
                    break;  
                case &quot;Kelvin&quot;:  
                    CelsiusToKelvin(temperature);  
                    break;  
                default:  
                    Console.WriteLine(&quot;Unknown conversion type.&quot;);  
                    break;  
            }        }  
        Console.WriteLine(&quot;Program closed.&quot;);  

    }  
    private static void CelsiusToFahrenheit(double celsius)  
    {        Console.ForegroundColor = ConsoleColor.Green;  
        Console.WriteLine($&quot;Fahrenheit: {celsius *  9 / 5}°F&quot;);  
        Console.ResetColor();  
    }  
    private static void CelsiusToKelvin(double celsius)  
    {        Console.ForegroundColor = ConsoleColor.Green;  
        Console.WriteLine($&quot;Kelvin: {celsius + 273.15}K&quot;);  
        Console.ResetColor();  
    }          
}

